bool readDatabaseFromStarZone(StarZone &zone) {
    if (!zone.canReadDatabaseName()) {
        zone.logError("Failed to read database name from zone.");
        return false;
    }

    std::string dbName, tableName;
    zone.readDatabaseName(dbName);
    zone.readTableName(tableName);

    // Store in member variables or relevant data structures
    this->setDatabaseName(dbName);
    this->setTableName(tableName);

    // Compatibility checks
    if (zone.isSqlStringSupported()) {
        std::string sqlString;
        if (!zone.readSqlString(sqlString)) {
            zone.logError("Failed to read SQL string from zone.");
            return true; // Partial success
        }
        this->setSqlString(sqlString);
    }

    if (zone.isDataEntrySupported()) {
        DataEntry data;
        if (!zone.readDataEntry(data)) {
            zone.logError("Failed to read data entry from zone.");
            return true; // Partial success
        }
        this->addDataEntry(data);
    }

    zone.logState("Finished reading database information from zone.");
    zone.closeRecord();
    return true;
}

bool readDatabaseNameAndData(StarZone& zone) {
    if (!zone.canReadDatabaseName()) {
        std::cerr << "Failed to read database name from zone." << std::endl;
        return false;
    }

    std::string dbName = zone.readDatabaseName();
    std::string tableName = zone.readTableName();

    if (zone.isVersionCompatible()) {
        std::string additionalSQL = zone.readAdditionalSQL();
        // Store additionalSQL as needed
    }

    bool success = true;
    if (!dbName.empty() && !tableName.empty()) {
        // Store dbName and tableName in member variables
        this->databaseName = dbName;
        this->tableName = tableName;
    } else {
        std::cerr << "Incomplete database or table name read." << std::endl;
        success = false;
    }

    // Read data entries if available
    while (zone.hasMoreDataEntries()) {
        DataEntry entry = zone.readDataEntry();
        if (!entry.isValid()) {
            std::cerr << "Invalid data entry encountered." << std::endl;
            success = false;
            break;
        }
        // Store entry as needed
        this->dataEntries.push_back(entry);
    }

    // Log the current state
    std::cerr << "Current state: DB=" << this->databaseName
              << ", Table=" << this->tableName
              << ", Entries=" << this->dataEntries.size() << std::endl;

    zone.closeRecord();
    return success;
}

bool readDatabaseFromStarZone(StarZone &zone) {
    if (!zone.canReadDatabaseName()) {
        zone.logError("Failed to read database name from zone.");
        return false;
    }

    std::string dbName, tableName;
    zone >> dbName >> tableName;
    this->setDatabaseName(dbName);
    this->setTableName(tableName);

    if (zone.isSQLCompatible()) {
        std::string sqlStr;
        zone >> sqlStr;
        this->setSQLString(sqlStr);
    }

    while (zone.hasMoreData()) {
        DataEntry entry;
        if (!zone.readDataEntry(entry)) {
            zone.logError("Failed to read data entry from zone.");
            return true;
        }
        this->addEntry(entry);
    }

    zone.logState("Finished reading data from zone. Current state: " + this->getState());
    zone.closeRecord();
    return true;
}
